/* generated child CSS: 14-pricing/pricing.matrix-collapsible/block.css */
/* lab-ui block · pricing.matrix-collapsible
   Depends: 00-tokens/tokens.css. Light theme. */

.mx-matrix {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
}
.mx-matrix .container {
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
}

/* ─── Header ────────────────────────────────────────────────── */
.mx-top {
  max-width: 54rem;
  margin: 0 auto clamp(2rem, 4vw, 3rem);
  text-align: center;
}
.mx-eyebrow {
  margin: 0 0 12px;
  font-family: var(--font-mono);
  font-size: var(--type-eyebrow-size);
  letter-spacing: var(--type-eyebrow-tracking);
  text-transform: uppercase;
  color: var(--color-text-accent);
}
.mx-title {
  margin: 0 0 12px;
  color: var(--color-heading);
  font-size: var(--type-h2-size);
  font-weight: var(--type-h2-weight);
  line-height: var(--type-h2-leading);
  letter-spacing: var(--type-h2-tracking);
}
.mx-lede {
  margin: 0;
  font-size: 1.0625rem;
  line-height: 1.55;
}

/* ─── Column count → grid tracks ───────────────────────────── */
.mx-matrix {
  --mx-feature-col: minmax(180px, 1.6fr);
  --mx-plan-cols: 4;
}
.mx-matrix[data-columns="2"] { --mx-plan-cols: 2; }
.mx-matrix[data-columns="3"] { --mx-plan-cols: 3; }
.mx-matrix[data-columns="4"] { --mx-plan-cols: 4; }

/* Hide non-selected plan columns in desktop AND accordion modes */
.mx-matrix[data-columns="2"] [data-plan-col="03"],
.mx-matrix[data-columns="2"] [data-plan-col="04"],
.mx-matrix[data-columns="3"] [data-plan-col="04"] {
  display: none;
}

/* ─── Table shell (desktop) ─────────────────────────────────── */
.mx-shell--table {
  position: relative;
  border: 1px solid rgba(146, 170, 205, 0.26);
  border-radius: var(--radius-card);
  background: var(--color-white);
  overflow: hidden;
}
.mx-row {
  display: grid;
  grid-template-columns: var(--mx-feature-col) repeat(var(--mx-plan-cols), minmax(0, 1fr));
  align-items: stretch;
  border-bottom: 1px solid rgba(146, 170, 205, 0.16);
}
.mx-row:last-child { border-bottom: 0; }
.mx-row--head {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--color-gray-bg);
  border-bottom: 1px solid rgba(146, 170, 205, 0.30);
}

.mx-cell {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
  padding: 16px 18px;
  font-size: 0.9375rem;
  color: var(--color-heading);
  border-right: 1px solid rgba(146, 170, 205, 0.10);
}
.mx-cell:last-child { border-right: 0; }
.mx-cell--feature {
  background: rgba(249, 249, 249, 0.6);
  color: var(--color-heading);
  font-weight: 600;
  border-right: 1px solid rgba(146, 170, 205, 0.22);
}
.mx-cell--plan {
  background: var(--color-gray-bg);
  text-align: left;
}
.mx-plan-name {
  font-size: 1.0625rem;
  font-weight: 650;
  color: var(--color-heading);
}
.mx-plan-tag {
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-gray-blue);
}
.mx-feature-label { font-weight: 600; }
.mx-feature-hint {
  font-weight: 400;
  font-size: 0.8125rem;
  color: var(--color-gray-blue);
}
.mx-feature-hint:empty { display: none; }

.mx-mobile-plan { display: none; }
.mx-value {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  min-height: 19px;
  position: relative;
}

/* ─── Cell states ───────────────────────────────────────────── */
.mx-cell[data-state="yes"]     .mx-value::before,
.mx-cell[data-state="no"]      .mx-value::before,
.mx-cell[data-state="partial"] .mx-value::before {
  content: "";
  display: inline-block;
  width: 19px;
  height: 19px;
  border-radius: 999px;
  flex: 0 0 19px;
}
.mx-cell[data-state="yes"]     .mx-value::before { background: var(--color-status-yes, #76D98F); }
.mx-cell[data-state="no"]      .mx-value::before { background: var(--color-status-no, #FF6B6B); }
.mx-cell[data-state="partial"] .mx-value::before { background: var(--color-status-partial, #D7D9DC); }
.mx-cell[data-state="yes"]     .mx-value::after,
.mx-cell[data-state="partial"] .mx-value::after {
  content: "";
  position: absolute;
  left: 5px;
  top: 8px;
  width: 8px;
  height: 4px;
  border-left: 2px solid #F9F9F9;
  border-bottom: 2px solid #F9F9F9;
  border-radius: 1px;
  transform: rotate(-45deg);
}
.mx-cell[data-state="no"] .mx-value::after {
  content: "";
  position: absolute;
  left: 5px;
  top: 5px;
  width: 9px;
  height: 9px;
  background:
    linear-gradient(45deg, transparent calc(50% - 1px), #F9F9F9 calc(50% - 1px), #F9F9F9 calc(50% + 1px), transparent calc(50% + 1px)),
    linear-gradient(-45deg, transparent calc(50% - 1px), #F9F9F9 calc(50% - 1px), #F9F9F9 calc(50% + 1px), transparent calc(50% + 1px));
}
.mx-cell[data-state="yes"] .mx-value:empty,
.mx-cell[data-state="partial"] .mx-value:empty,
.mx-cell[data-state="no"] .mx-value:empty {
  gap: 0;
}
.mx-cell[data-state="no"] .mx-value { color: var(--color-gray-blue); }

/* ─── Group title row ───────────────────────────────────────── */
.mx-group { display: contents; }
.mx-group[data-group-visible="hide"] { display: none; }
.mx-row[data-row-visible="hide"] { display: none; }
.mx-group-title {
  grid-column: 1 / -1;
  padding: 18px 18px 10px;
  background: var(--color-white);
  color: var(--color-text-accent);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  border-bottom: 1px solid rgba(146, 170, 205, 0.20);
  border-top: 1px solid rgba(146, 170, 205, 0.16);
}
.mx-group:first-of-type .mx-group-title { border-top: 0; }

/* ─── Accordion shell (mobile) ─────────────────────────────── */
.mx-shell--accordion { display: none; }

@media (max-width: 720px) {
  .mx-matrix .container { padding-inline: 18px; }
  .mx-shell--table { display: none; }
  .mx-shell--accordion {
    display: grid;
    gap: 10px;
  }
  .mx-acc {
    border: 1px solid rgba(146, 170, 205, 0.26);
    border-radius: var(--radius-card);
    background: var(--color-white);
    overflow: hidden;
  }
  .mx-acc[open] { box-shadow: var(--shadow-1); }
  .mx-acc-summary {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 18px 20px;
    cursor: pointer;
    list-style: none;
  }
  .mx-acc-summary::-webkit-details-marker { display: none; }
  .mx-acc-name {
    flex: 1;
    color: var(--color-heading);
    font-size: 1.0625rem;
    font-weight: 650;
  }
  .mx-acc-tag {
    padding: 3px 9px;
    border-radius: var(--radius-pill);
    background: var(--cta-accent-soft);
    color: var(--color-heading);
    font-family: var(--font-mono);
    font-size: 0.6875rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }
  .mx-acc-chev {
    width: 10px;
    height: 10px;
    border-right: 2px solid var(--color-gray-blue);
    border-bottom: 2px solid var(--color-gray-blue);
    transform: rotate(45deg);
    transition: transform var(--transition-fast);
  }
  .mx-acc[open] .mx-acc-chev { transform: rotate(-135deg); }
  .mx-acc-body {
    padding: 0 20px 18px;
    border-top: 1px solid rgba(146, 170, 205, 0.18);
  }
  .mx-acc-group { padding-top: 14px; }
  .mx-acc-group[data-group-visible="hide"] { display: none; }
  .mx-acc-group-title {
    margin: 0 0 8px;
    color: var(--color-text-accent);
    font-family: var(--font-mono);
    font-size: 0.6875rem;
    letter-spacing: 0.10em;
    text-transform: uppercase;
  }
  .mx-acc-list { margin: 0; padding: 0; display: grid; gap: 4px; }
  .mx-acc-item {
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 12px;
    padding: 8px 0;
    border-bottom: 1px dashed rgba(146, 170, 205, 0.22);
  }
  .mx-acc-item[data-row-visible="hide"] { display: none; }
  .mx-acc-item:last-child { border-bottom: 0; }
  .mx-acc-item dt {
    color: var(--color-text);
    font-size: 0.875rem;
  }
  .mx-acc-item dd {
    margin: 0;
    color: var(--color-heading);
    font-size: 0.875rem;
    font-weight: 600;
    text-align: right;
  }
  .mx-acc-item dd[data-state="yes"],
  .mx-acc-item dd[data-state="no"],
  .mx-acc-item dd[data-state="partial"] {
    display: inline-flex;
    align-items: center;
    justify-content: flex-end;
    gap: 10px;
    min-height: 19px;
    position: relative;
  }
  .mx-acc-item dd[data-state="yes"]::before,
  .mx-acc-item dd[data-state="no"]::before,
  .mx-acc-item dd[data-state="partial"]::before {
    content: "";
    display: inline-block;
    width: 19px;
    height: 19px;
    border-radius: 999px;
    flex: 0 0 19px;
  }
  .mx-acc-item dd[data-state="yes"]::before { background: var(--color-status-yes, #76D98F); }
  .mx-acc-item dd[data-state="no"]::before { background: var(--color-status-no, #FF6B6B); }
  .mx-acc-item dd[data-state="partial"]::before { background: var(--color-status-partial, #D7D9DC); }
  .mx-acc-item dd[data-state="yes"]::after,
  .mx-acc-item dd[data-state="partial"]::after {
    content: "";
    position: absolute;
    left: 5px;
    top: 8px;
    width: 8px;
    height: 4px;
    border-left: 2px solid #F9F9F9;
    border-bottom: 2px solid #F9F9F9;
    border-radius: 1px;
    transform: rotate(-45deg);
  }
  .mx-acc-item dd[data-state="no"]::after {
    content: "";
    position: absolute;
    left: 5px;
    top: 5px;
    width: 9px;
    height: 9px;
    background:
      linear-gradient(45deg, transparent calc(50% - 1px), #F9F9F9 calc(50% - 1px), #F9F9F9 calc(50% + 1px), transparent calc(50% + 1px)),
      linear-gradient(-45deg, transparent calc(50% - 1px), #F9F9F9 calc(50% - 1px), #F9F9F9 calc(50% + 1px), transparent calc(50% + 1px));
  }
  .mx-acc-item dd[data-state="no"] { color: var(--color-gray-blue); font-weight: 400; }
  .mx-acc-item dd[data-state="yes"]:empty,
  .mx-acc-item dd[data-state="partial"]:empty,
  .mx-acc-item dd[data-state="no"]:empty {
    gap: 0;
  }
}

.mx-disclaimer {
  margin: 22px 0 0;
  color: var(--color-gray-blue);
  font-size: 0.8125rem;
  line-height: 1.5;
  text-align: center;
}

